    margin: 6px 0 3px 0;
    line-height: 1.22;
  }

  /* גריד העמוד המרכזי */
  .page-content-grid {
    display: grid;
    grid-template-columns: var(--w-margin) var(--w-gap) var(--w-col) var(--w-gutter) var(--w-col) var(--w-gap) var(--w-margin);
    position: relative;
    align-items: start;
    height: 875px;
  }

  .page-content-grid.has-h2 {
    height: 660px;
  }

  /* שוליים לכותרות צד (רמה 7) */
  .margin-notes-column {
    font-family: var(--fn-h7);
    font-size: var(--sz-h7);
    line-height: 1.18;
    text-align: center;
    text-align-last: center;
    font-weight: 400;
    color: #404040;
    position: relative;
    width: 100%;
    height: 100%;
  }

  .right-margin { grid-column: 1; }
  .left-margin { grid-column: 7; }

  .side-note-anchor {
    position: absolute;
    width: 100%;
  }

  /* טורי הטקסט המרכזיים */
  .main-column {
    font-family: var(--fn-body);
    font-size: var(--sz-body);
    line-height: 1.34;
    text-align: justify;
    text-justify: inter-word;
    min-height: 0;
    height: auto;
    position: relative;
  }

  .right-col { grid-column: 3; }
  .left-col { grid-column: 5; }

  p {
    margin-bottom: 7px;
    text-align: justify;
    text-justify: inter-word;
    position: relative;
  }

  p.p-end { text-align-last: center; }
  p.p-cut { text-align-last: justify; }

  /* חלון מילה ראשונה מוגדלת */
  .first-word-window {
    float: right;
    font-family: var(--fn-first-word);
    font-size: var(--sz-first-word);
    font-weight: 900;
    line-height: 0.85;
    height: 1.25em;
    margin-left: 6px;
    margin-bottom: 1px;
    display: block;
  }

  /* מספר עמוד (Footer) */
  .page-number-footer {
    position: absolute;
    bottom: 14mm;
    left: 0;
    right: 0;
    text-align: center;
    font-family: var(--fn-header);
    font-size: 12pt;
    font-weight: 700;
    height: 20px;
  }

  @media print {
    body { background: none; padding: 0; overflow: visible; display: block; }
    #sidebar { display: none !important; }
    #preview-pane { height: auto !important; overflow: visible !important; padding: 0 !important; }
    .a4-page {
      box-shadow: none;
      width: 100%;
      height: 100%;
      min-height: 100vh;
      max-height: 100vh;
      padding: 15mm 15mm 15mm 15mm;
      margin: 0;
      page-break-after: always;
    }
  }
</style>
</head>
