    <!-- 5. טיפוגרפיה וחלון מילה ראשונה -->
    <section id="section-typography" class="doc-section">
      <h2 class="section-title">5. טיפוגרפיה מתקדמת: "חלון" פתוח ויישור שורות</h2>

      <h3>א. חלון מילה ראשונה (Drop-Word Window)</h3>
      <p>במקום אות גדולה (Drop-Cap) הנהוגה בספרות לועזית, בספרי קודש נהוג להגדיל את <b>המילה הראשונה כולה</b> באותיות מרובעות שמנות, כאשר השורה השנייה של הפסקה נכנסת מתחתיה ויוצרת "חלון" טיפוגרפי פתוח:</p>

      <pre><code>/* הטריק הטיפוגרפי של החלון התורני */
.first-word-window {
  float: right;
  font-family: var(--fn-first-word); /* גופן עצמאי למילה ראשונה */
  font-size: var(--sz-first-word);   /* גודל 1.5em */
  font-weight: 900;
  line-height: 0.85;
  height: 1.25em; /* גובה מאולץ שגורם לשורה השנייה להתחיל מתחת למילה */
  margin-left: 6px;
  margin-bottom: 1px;
  display: block;
}</code></pre>

      <h3>ב. יישור שורות מותנה (Conditional Line Justification)</h3>
      <p>כאשר פסקה שלמה מסתיימת, מנהג הישיבות ששורת הסיום מיושרת לאמצע הדף. אולם, כאשר פסקה נחצית בסוף טור ועוברת לטור הבא – אסור ליישר את שורת החיתוך לאמצע (דבר שיוצר רווח ריק מוזר ברצף הקריאה). הפתרון בקוד מבוסס על שתי מחלקות CSS חכמות:</p>

      <pre><code>/* פסקה שמסתיימת לגמרי - שורה אחרונה במרכז */
p.p-end { text-align-last: center; }

/* פסקה שנחתכה וממשיכה בטור הבא - שורה אחרונה מיושרת לשני הצדדים ברצף מלא */
p.p-cut { text-align-last: justify; }</code></pre>
    </section>

    <!-- 6. אלגוריתמים ומנוע ה-JS -->
    <section id="section-balancing" class="doc-section">
      <h2 class="section-title">6. אלגוריתם איזון סופי פרקים (Pre-Balancing Engine)</h2>

      <p><b>מדוע מנגנון האיזון הישן נכשל?</b><br>
      בעבר המנוע מילא את טור ימין במלואו (עד 875px) ולאחר מכן ניסה להעביר פסקאות שלמות לטור שמאל. אם פסקה הייתה ארוכה (200px), לא ניתן היה לפצל אותה בדיעבד, והטור השמאלי נמתח ברווחים מוגזמים של 70px בין שורות או נשאר חצי ריק.</p>

      <p><b>הפתרון החדש: חישוב נקודת אמצע מקדימה (Pre-Balancing)</b><br>
      בטרם תחילת מילוי העמוד, המערכת מודדת את סך כל הגובה של הטקסט שנותר במקטע באמצעות תיבת מדידה מוסתרת ב-DOM (`#measuring-box`). אם הטקסט נכנס בעמוד בודד ($H_{\text{rem}} \le 2 \times \text{maxH}$), נקבע יעד גובה מדויק לשני הטורים:</p>

      <pre><code>// חישוב גובה יעד מאוזן לסוף פרק
const totalRemH = measureRemainingHeight(secTokens, tokenIndex, pendingWordTokens, actualColWidth);
const isSectionClosingPage = totalRemH <= (2 * pageLayout.maxColHeight);

if (isSectionClosingPage) {
  // חצי מדויק לכל טור + 4px גמישות
  targetHeightPerColumn = Math.min(pageLayout.maxColHeight, Math.max(60, Math.ceil(totalRemH / 2) + 4));
}</code></pre>

      <p>טור ימין מתמלא בדיוק עד `targetHeightPerColumn` (אם צריך לחתוך פסקה – היא נחתכת מילה-במילה), וטור שמאל קולט את החצי השני. התוצאה: <b>שני הטורים מסתיימים באותו גובה בדיוק של 100% ללא מרווחי פסקאות מעוותים.</b></p>
    </section>

    <!-- 7. מניעת כותרות יתומות -->
    <section id="section-orphans" class="doc-section">
      <h2 class="section-title">7. מניעת כותרות יתומות (רמות 3 עד 6)</h2>
      <p>בהלכות עימוד דפוס, כותרת אינה יכולה להופיע בתחתית עמוד או טור כ"יתומה" (Orphan Heading) ללא גוף הטקסט שלה. הקוד בודק עבור כל כותרת מרמות 3, 4, 5, 6 האם נותר בטור מקום עבור <b>הכותרת + לפחות 2 שורות מתוכנה (כ-45-50px)</b>:</p>

      <pre><code>// בדיקת חוק יתומים לרמות 3-6
if (currentTok.type.startsWith('h')) {
  const hElem = document.createElement('div');
  hElem.className = `title-level-${currentTok.level}`;
  hElem.textContent = currentTok.text;
  targetCol.appendChild(hElem);

  // אם הכותרת גולשת לאזור 45px האחרונים של הטור - דוחים אותה לטור הבא
  if (targetCol.scrollHeight > effectiveColLimit - 45 && targetCol.children.length > 1) {
    targetCol.removeChild(hElem);
    break; // סגירת הטור והעברת הכותרת לראש הטור הבא
  }
}</code></pre>
    </section>

    <!-- 8. הצדקה אנכית -->
    <section id="section-feathering" class="doc-section">
      <h2 class="section-title">8. מנגנון הצדקה אנכית (Vertical Feathering)</h2>
      <p>כאשר כותרת נדחית לטור הבא, הטור הקודם עלול להסתיים מעט מוקדם יותר. פונקציית `justifyColumnVertically` מפזרת את יתרת הפיקסלים (עד 160px) באופן שווה ועדין בין ה-`margin-bottom` של כל הפסקאות בטור:</p>

      <pre><code>function justifyColumnVertically(col, maxH) {
  const children = Array.from(col.children);
  if (children.length <= 1) return;
  const currentH = col.scrollHeight;
  const diff = maxH - currentH;

  // אם יש פער קטן עד בינוני - מותחים את המרווחים בעדינות שווה
  if (diff > 2 && diff < 160) {
    const extraPerItem = diff / (children.length - 1);
    children.slice(0, -1).forEach(child => {
      const curMB = parseFloat(getComputedStyle(child).marginBottom) || 0;
      child.style.marginBottom = (curMB + extraPerItem) + 'px';
    });
  }
}</code></pre>
    </section>

    <!-- 9. סנכרון סמן -->
    <section id="section-sync" class="doc-section">
      <h2 class="section-title">9. סנכרון סמן עורך (Bidirectional Cursor Sync)</h2>
      <p>המערכת יוצרת מיפוי מדויק בין מספרי השורות בתיבת ה-`textarea` לבין מזהה הטוקן (`data-token-id`) בעמודים המעומדים. בעת קליק או לחיצה על מקשי החצים בתיבת הטקסט, העמוד הרלוונטי נגלל אוטומטית למרכז התצוגה:</p>

      <pre><code>function syncCursorToPreview() {
  const cursorPos = textarea.selectionStart;
  const textBefore = textarea.value.substring(0, cursorPos);
  const currentLineIdx = textBefore.split('\n').length - 1;

  let tokenId = lineToTokenMap[currentLineIdx];
  if (tokenId !== null && tokenId !== undefined) {
    const targetEl = document.querySelector(`[data-token-id="${tokenId}"]`);
    if (targetEl) {
      targetEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  }
}

textarea.addEventListener('click', syncCursorToPreview);
textarea.addEventListener('keyup', syncCursorToPreview);</code></pre>
    </section>

    <!-- 10. ריכוז הדיוקים -->
    <section id="section-refinements" class="doc-section">
      <h2 class="section-title">10. ריכוז הדיוקים והאתגרים שנפתרו לאורך הפיתוח</h2>

