  .proportions-grid, .styles-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 5px 10px;
    font-size: 8.5pt;
  }

  .prop-item, .style-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
  }

  .style-item label { font-weight: 700; width: 85px; }
  .style-item select { padding: 2px; font-size: 8pt; width: 100px; }
  .style-item input { width: 38px; padding: 2px; text-align: center; font-size: 8pt; }

  .textarea-container {
    display: flex;
    flex-direction: column;
    min-height: 110px;
    height: 120px;
    margin-bottom: 8px;
