  .btn-bar { display: flex; gap: 6px; margin-bottom: 6px; }
  .btn-primary {
    background-color: #000;
    color: #fff;
    border: none;
    padding: 7px 14px;
    font-size: 10.5pt;
    font-weight: 700;
    cursor: pointer;
    border-radius: 3px;
    flex-grow: 1;
  }
  .btn-secondary {
    background-color: #f0f0f0;
    color: #000;
    border: 1px solid #666;
    padding: 7px 12px;
    font-size: 10pt;
    cursor: pointer;
    border-radius: 3px;
  }

  /* -------------------------------------------------------------
     תצוגת דפים מעומדים משמאל
  ------------------------------------------------------------- */
  #preview-pane {
    flex-grow: 1;
    height: 100vh;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 25px 20px;
    scroll-behavior: smooth;
  }

  .a4-page {
    background-color: #ffffff;
    width: 210mm;
    height: 297mm;
    max-height: 297mm;
    padding: 15mm 15mm 15mm 15mm;
