        </div>
        <div class="form-group">
          <label>נושא מפורט / תיאור:</label>
          <input type="text" id="inp-book-desc" value="ביאור מקיף ועמוק ביסודות המלאכה, גדרי מעשה ומחשבה, מבנה הרשויות, מחיצות, עירובי חצרות ותחומין לאור סוגיות השס והראשונים" oninput="typesetDocument()">
        </div>
