      const hdrCType = document.getElementById('hdr-c-type').value;
      const hdrCAlign = document.getElementById('hdr-c-align').value;
      const hdrCCustom = document.getElementById('hdr-c-custom').value;
      const hdrCHTML = renderHeaderSectionHTML(hdrCType, hdrCCustom, h1Title, h2Title, '', bookTitle);

      const hdrLType = document.getElementById('hdr-l-type').value;
      const hdrLAlign = document.getElementById('hdr-l-align').value;
      const hdrLCustom = document.getElementById('hdr-l-custom').value;
      const hdrLHTML = renderHeaderSectionHTML(hdrLType, hdrLCustom, h1Title, h2Title, '', bookTitle);

      page.innerHTML = `
